#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────

# Weekly backup setup for ticket #22: the encryption key and the production key as GitHub
# Actions secrets, then (after Sprint 2 ships) the first backup and the one real restore test.
# Run it from anywhere: it moves to the repo root first.
cd "$(dirname "$0")/.."

# The key stays on this Mac in .env.backup (git-ignored by .env*), so the restore check can open
# the backups. Nothing else is written to a file.
ENV_FILE=".env.backup"
SUPABASE_PROJECT_REF="hvavvhzxbifqnufmrucl"
PRODUCTION_SUPABASE_URL="https://$SUPABASE_PROJECT_REF.supabase.co"
GITHUB_ACCOUNT="lam-valamorgulis"
REPO="lam-valamorgulis/tech-lead-trainer"

TOTAL_STAGES=5

banner "Tech Lead Trainer: weekly backup"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This wizard stores 3 secrets in GitHub for the weekly backup. It takes about 5 minutes."
say "Checking that gh can use your personal account…"
if ! GH_TOKEN=$(gh auth token --user "$GITHUB_ACCOUNT" 2>/dev/null); then
  warn "gh has no login for $GITHUB_ACCOUNT. Run: gh auth login, then run this wizard again."
  exit 1
fi
export GH_TOKEN
if ! gh repo view "$REPO" >/dev/null 2>&1; then
  warn "gh cannot open $REPO with the $GITHUB_ACCOUNT account."
  exit 1
fi
printf '  %s✓%s gh works for %s\n' "$GREEN" "$RESET" "$REPO"
pause

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Make the encryption key"
say "Every backup is locked with this key. Without it, no backup can be opened."
BACKUP_ENCRYPTION_KEY=$(_existing BACKUP_ENCRYPTION_KEY || true)
if [[ -n "$BACKUP_ENCRYPTION_KEY" ]]; then
  printf '  %s✓%s using the key already in %s\n' "$GREEN" "$RESET" "$ENV_FILE"
  note "Keep it: backups made with this key need this key to open."
else
  BACKUP_ENCRYPTION_KEY=$(openssl rand -base64 32)
  write_env BACKUP_ENCRYPTION_KEY "$BACKUP_ENCRYPTION_KEY"
fi
chmod 600 "$ENV_FILE"
say "Save a second copy outside this Mac. If the Mac breaks, that copy is the only way in."
printf '%s' "$BACKUP_ENCRYPTION_KEY" | pbcopy
step "The key is on your clipboard now. It is not shown here."
step "Paste it into your password manager as a new item: \"Tech Lead Trainer backup key\". Save it."
pause "Press Enter after you saved it"
pbcopy < /dev/null
note "Clipboard cleared."

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Read the production secret key"
say "The weekly job reads every table with the Supabase secret key (it starts with sb_secret_)."
say "Reading it through your Supabase CLI login. It is not shown here."
PRODUCTION_SUPABASE_SECRET_KEY=$(npx supabase projects api-keys --project-ref "$SUPABASE_PROJECT_REF" --reveal -o json 2>/dev/null \
  | node -e '
      let text = "";
      process.stdin.on("data", (chunk) => (text += chunk));
      process.stdin.on("end", () => {
        const found = [];
        const walk = (value) => {
          if (typeof value === "string" && /^sb_secret_[A-Za-z0-9_-]+$/.test(value)) found.push(value);
          else if (value && typeof value === "object") Object.values(value).forEach(walk);
        };
        try { walk(JSON.parse(text)); } catch {}
        process.stdout.write(found[0] ?? "");
      });' || true)
if [[ -z "$PRODUCTION_SUPABASE_SECRET_KEY" ]]; then
  warn "The CLI did not give a secret key. Not signed in? Run: npx supabase login"
  say "Or copy it by hand:"
  open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/settings/api-keys"
  step "Find the secret key (sb_secret_…). Reveal it and copy the whole key."
  note "A key that ends with dots is masked. Reveal it first."
  ask_secret PRODUCTION_SUPABASE_SECRET_KEY "Paste the secret key:"
fi
until [[ "$PRODUCTION_SUPABASE_SECRET_KEY" =~ ^sb_secret_[A-Za-z0-9_-]+$ ]]; do
  ask_secret PRODUCTION_SUPABASE_SECRET_KEY "That is not a full sb_secret_ key. Paste it again:"
done
printf '  %s✓%s secret key read (%s characters)\n' "$GREEN" "$RESET" "${#PRODUCTION_SUPABASE_SECRET_KEY}"
pause

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Store the 3 GitHub secrets"
say "Only the weekly backup job reads them. GitHub never shows a secret again."
set_secret PRODUCTION_SUPABASE_URL "$PRODUCTION_SUPABASE_URL"
set_secret PRODUCTION_SUPABASE_SECRET_KEY "$PRODUCTION_SUPABASE_SECRET_KEY"
set_secret BACKUP_ENCRYPTION_KEY "$BACKUP_ENCRYPTION_KEY"
unset PRODUCTION_SUPABASE_SECRET_KEY
say "Secrets on GitHub now:"
gh secret list --repo "$REPO" | grep -E '^(PRODUCTION_SUPABASE_URL|PRODUCTION_SUPABASE_SECRET_KEY|BACKUP_ENCRYPTION_KEY)\b' || warn "Could not list the secrets."
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "First backup and the restore test (after the ship)"
say "The job runs only after Sprint 2 is on main, and production has the backups table."
if confirm "Is Sprint 2 shipped? Start the first backup now?"; then
  gh workflow run backup.yml --repo "$REPO" --ref main
  say "Started. Waiting for GitHub to show the run…"
  sleep 8
  RUN_ID=$(gh run list --repo "$REPO" --workflow backup.yml --limit 1 --json databaseId --jq '.[0].databaseId')
  gh run watch "$RUN_ID" --repo "$REPO" --exit-status || warn "The backup run failed. Open it: gh run view $RUN_ID --repo $REPO --log-failed"
  say "Now the one real restore test, into a new empty database on this Mac:"
  step "npm run db:start   (if local Supabase is not running)"
  step "git fetch origin backups && npm run backup:restore-check"
  note "PASS means every row came back and the review state is the same."
else
  SKIPPED+=("After the ship: gh workflow run backup.yml --ref main, then git fetch origin backups && npm run backup:restore-check")
fi

finish
say "Settings in the app shows \"Last backup: <date>\" after the first backup."
printf '\n'
